1	import { Block, Text } from "@prototyp/skeletor";
2	import { useIsFocused } from "@react-navigation/native";
3	import type { NativeStackScreenProps } from "@react-navigation/native-stack";
4	import {
5	  MembershipState_Tags,
6	  StateEventType,
7	} from "@unomed/react-native-matrix-sdk";
8	import { useAtomValue, useSetAtom } from "jotai";
9	import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
10	import { NetworkAtoms } from "modules/network/jotai";
11	import { useRoomInfo, useRoomMembers } from "modules/room/hooks";
12	import { RoomAtoms } from "modules/room/jotai";
13	import { RoomService } from "modules/room/service/RoomService";
14	import { TimelineAtoms } from "modules/timeline/jotai";
15	import { useCallback, useEffect, useMemo, useState } from "react";
16	import { Image, StyleSheet, Switch } from "react-native";
17	import { SettingsListItem } from "screens/settings/fragments";
18	import {
19	  Button,
20	  GoBackHeader,
21	  IpadScreenWrapper,
22	  Loading,
23	  RoomImage,
24	  ScreenLayout,
25	} from "shared/components";
26	import { useLeaveRoom } from "shared/hooks";
27	import { Colors, TextSize } from "shared/styles";
28	import { offlineToastHelper } from "shared/utils";
29	import { ActionButtons, EncryptionStatus, Topic } from "./fragments";
30	import { LeaveRoom } from "./leave-room/LeaveRoom";
31	
32	export const RoomDetails: React.FC<
33	  NativeStackScreenProps<Routes, "roomDetails">
34	> = ({ navigation, route }) => {
35	  const { room } = route.params;
36	  const roomInfo = useRoomInfo(room);
37	  const isFocused = useIsFocused();
38	  const isOffline = useAtomValue(NetworkAtoms.isOffline);
39	  const isDirect = roomInfo?.isDirect;
40	  const hasPowerLevelToCall =
41	    roomInfo?.powerLevels?.canOwnUserSendState(StateEventType.CallMember) ??
42	    false;
43	  const { members, fetchMembers } = useRoomMembers(room);
44	  const { isLeavingRoom, leaveRoom } = useLeaveRoom(room, members, {
45	    onSuccess: () => {
46	      navigation.reset({
47	        index: 0,
48	        routes: [{ name: "home" }],
49	      });
50	    },
51	  });
52	  const [isFavorite, setIsFavorite] = useState(false);
53	  const [isFavoriteLoading, setIsFavoriteLoading] = useState(false);
54	  const [userPowerLevel, setUserPowerLevel] = useState<number | null>(null);
55	  const [nameLevel, setNameLevel] = useState(50);
56	  const [avatarLevel, setAvatarLevel] = useState(50);
57	  const [topicLevel, setTopicLevel] = useState(50);
58	  const [inviteLevel, setInviteLevel] = useState<number>(50);
59	  const setRoomNotificationMode = useSetAtom(RoomAtoms.roomNotificationMode);
60	  const setImageViewerPayload = useSetAtom(TimelineAtoms.imageViewerPayload);
61	
62	  const canSeeRoles = useMemo(
63	    () => !!userPowerLevel && userPowerLevel >= 50,
64	    [userPowerLevel],
65	  );
66	  const canEditName = useMemo(
67	    () => (userPowerLevel ?? 0) >= nameLevel,
68	    [userPowerLevel, nameLevel],
69	  );
70	  const canEditAvatar = useMemo(
71	    () => (userPowerLevel ?? 0) >= avatarLevel,
72	    [userPowerLevel, avatarLevel],
73	  );
74	  const canEditTopic = useMemo(
75	    () => (userPowerLevel ?? 0) >= topicLevel,
76	    [userPowerLevel, topicLevel],
77	  );
78	  const canEditRoom = useMemo(
79	    () => !isDirect && (canEditName || canEditAvatar || canEditTopic),
80	    [isDirect, canEditName, canEditAvatar, canEditTopic],
81	  );
82	  const canInvite = useMemo(
83	    () => !isDirect && userPowerLevel !== null && userPowerLevel >= inviteLevel,
84	    [userPowerLevel, inviteLevel],
85	  );
86	  const pinnedEventIds = useAtomValue(TimelineAtoms.pinnedEventIds);
87	  const otherDirectMember = useMemo(() => {
88	    return members.filter(
89	      (member) => member.userId !== MatrixCore.instance?.userId(),
90	    )[0];
91	  }, [members]);
92	  const otherDirectMembersId = otherDirectMember?.userId;
93	
94	  // Sync isFavourite from live roomInfo
95	  useEffect(() => {
96	    if (!roomInfo) return;
97	    setIsFavorite(roomInfo.isFavourite ?? false);
98	  }, [roomInfo?.isFavourite]);
99	
100	  useEffect(() => {
101	    if (!isFocused) return;
102	
103	    RoomService.getUserPowerLevel(room.id())
104	      .then(setUserPowerLevel)
105	      .catch(console.error);
106	
107	    RoomService.getRoomPowerLevels(room.id())
108	      .then((pl) => {
109	        if (!pl) return;
110	        const vals = pl.values();
111	        setNameLevel(Number(vals.roomName));
112	        setAvatarLevel(Number(vals.roomAvatar));
113	        setTopicLevel(Number(vals.roomTopic));
114	        setInviteLevel(Number(vals.invite));
115	      })
116	      .catch(console.error);
117	
118	    MatrixCore.getClient()
119	      .getNotificationSettings()
120	      .then((ns) => ns.getUserDefinedRoomNotificationMode(room.id()))
121	      .then((mode) => setRoomNotificationMode(mode ?? null))
122	      .catch(console.error);
123	  }, [isFocused]);
124	
125	  useEffect(() => {
126	    if (!isFocused) return;
127	    fetchMembers();
128	  }, [isFocused, fetchMembers]);
129	
130	  const handleToggleFavourite = useCallback(async () => {
131	    if (isOffline) {
132	      offlineToastHelper("No internet connection");
133	      return;
134	    }
135	
136	    if (isFavoriteLoading) return;
137	    setIsFavoriteLoading(true);
138	    setIsFavorite(!isFavorite);
139	    try {
140	      await room.setIsFavourite(!isFavorite, undefined);
141	    } catch (error) {
142	      setIsFavorite(isFavorite);
143	      console.error(error);
144	      offlineToastHelper(
145	        isFavorite
146	          ? "Failed to remove from favorites"
147	          : "Failed to add to favorites",
148	      );
149	    } finally {
150	      setIsFavoriteLoading(false);
151	    }
152	  }, [isFavorite, isOffline, isFavoriteLoading, room]);
153	
154	  if (!roomInfo) return <Loading />;
155	
156	  return (
157	    <ScreenLayout>
158	      {isLeavingRoom && <Loading text="Leaving room..." />}
159	      <GoBackHeader
160	        margins={{ marginBottom: 40 }}
161	        rightComp={
162	          canEditRoom && (
163	            <Button.Wrapper
164	              onPress={() =>
165	                navigation.navigate("editRoom", {
166	                  room,
167	                })
168	              }
169	            >
170	              <Text>Edit</Text>
171	            </Button.Wrapper>
172	          )
173	        }
174	      />
175	      <IpadScreenWrapper width="100%" scrollable>
176	        <Block align="center" gap={12}>
177	          <RoomImage
178	            onPress={(uri) => setImageViewerPayload({ uri })}
179	            room={room}
180	            width={80}
181	            height={80}
182	          />
183	          <Text size={TextSize.medium} font="InstrumentSans-Bold">
184	            {room.displayName()}
185	          </Text>
186	          {isDirect && roomInfo?.heroes[0]?.userId && (
187	            <Text color={Colors.white50}>{roomInfo?.heroes[0]?.userId}</Text>
188	          )}
189	          <EncryptionStatus roomInfo={roomInfo} />
190	        </Block>
191	        <ActionButtons
192	          room={room}
193	          members={members}
194	          hasPowerLevelToCall={hasPowerLevelToCall}
195	          canInvite={canInvite}
196	        />
197	        <Topic room={room} topic={roomInfo?.topic} canEdit={canEditTopic} />
198	        <Block
199	          border={{ borderRadius: 16 }}
200	          width="100%"
201	          background={Colors.white5}
202	          margins={{ marginBottom: 20 }}
203	        >
204	          <SettingsListItem
205	            title="Notifications"
206	            icon={require("assets/icons/bell.png")}
207	            showSeparator
208	            onPress={() =>
209	              navigation.navigate("roomNotifications", { roomId: room.id() })
210	            }
211	          />
212	          <SettingsListItem
213	            title="Favorite"
214	            icon={require("assets/icons/star.png")}
215	            showSeparator
216	            onPress={handleToggleFavourite}
217	            rightComp={
218	              <Block paddings={{ paddingRight: 12 }}>
219	                <Switch
220	                  value={isFavorite}
221	                  disabled={isFavoriteLoading}
222	                  trackColor={{ true: Colors.primary, false: Colors.white20 }}
223	                  onValueChange={handleToggleFavourite}
224	                />
225	              </Block>
226	            }
227	          />
228	          {isDirect ? (
229	            <Button.Wrapper
230	              onPress={() =>
231	                navigation.navigate("profile", {
232	                  userId: otherDirectMembersId,
233	                  initialProfile: otherDirectMember
234	                    ? {
235	                        userId: otherDirectMember.userId,
236	                        displayName: otherDirectMember.displayName,
237	                        avatarUrl: otherDirectMember.avatarUrl,
238	                      }
239	                    : undefined,
240	                })
241	              }
242	            >
243	              <Block paddings={[0, 12]}>
244	                <Block
245	                  flexDirection="row"
246	                  align="center"
247	                  gap={12}
248	                  paddings={[20, 0]}
249	                  border={{ borderBottomWidth: 1, borderColor: Colors.white5 }}
250	                >
251	                  <Image
252	                    source={require("assets/icons/user.png")}
253	                    tintColor={Colors.white50}
254	                    width={24}
255	                    height={24}
256	                  />
257	                  <Text>View profile</Text>
258	                  <Block
259	                    margins={{ marginLeft: "auto" }}
260	                    flexDirection="row"
261	                    align="center"
262	                    gap={8}
263	                  >
264	                    <Image
265	                      source={require("assets/icons/caret-left.png")}
266	                      style={styles.caret}
267	                      tintColor={Colors.white50}
268	                    />
269	                  </Block>
270	                </Block>
271	              </Block>
272	            </Button.Wrapper>
273	          ) : (
274	            <Button.Wrapper
275	              onPress={() =>
276	                navigation.navigate("roomMembers", {
277	                  roomId: room.id(),
278	                })
279	              }
280	            >
281	              <Block paddings={[0, 12]}>
282	                <Block
283	                  flexDirection="row"
284	                  align="center"
285	                  gap={12}
286	                  paddings={[20, 0]}
287	                  border={{ borderBottomWidth: 1, borderColor: Colors.white5 }}
288	                >
289	                  <Image
290	                    source={require("assets/icons/users.png")}
291	                    tintColor={Colors.white50}
292	                    width={24}
293	                    height={24}
294	                  />
295	                  <Text>Members</Text>
296	                  <Block
297	                    margins={{ marginLeft: "auto" }}
298	                    flexDirection="row"
299	                    align="center"
300	                    gap={8}
301	                  >
302	                    <Text color={Colors.white50}>
303	                      (
304	                      {
305	                        members.filter(
306	                          (m) =>
307	                            m.membership?.tag === MembershipState_Tags.Join,
308	                        ).length
309	                      }
310	                      )
311	                    </Text>
312	                    <Image
313	                      source={require("assets/icons/caret-left.png")}
314	                      style={styles.caret}
315	                      tintColor={Colors.white50}
316	                    />
317	                  </Block>
318	                </Block>
319	              </Block>
320	            </Button.Wrapper>
321	          )}
322	          {!isDirect && canSeeRoles && (
323	            <SettingsListItem
324	              title="Security & Privacy"
325	              icon={require("assets/icons/shield.png")}
326	              showSeparator
327	              onPress={() => navigation.navigate("roomSecurity", { room })}
328	            />
329	          )}
330	          {!isDirect && canSeeRoles && (
331	            <SettingsListItem
332	              title="Roles & Permissions"
333	              icon={require("assets/icons/user.png")}
334	              showSeparator
335	              onPress={() =>
336	                navigation.navigate("roomRoles", {
337	                  room,
338	                  userPowerLevel: userPowerLevel ?? 0,
339	                })
340	              }
341	            />
342	          )}
343	          <SettingsListItem
344	            title="Media and Files"
345	            icon={require("assets/icons/image.png")}
346	            onPress={() => navigation.navigate("roomMedia", { room })}
347	            showSeparator={!!pinnedEventIds.length}
348	          />
349	          {!!pinnedEventIds.length && (
350	            <SettingsListItem
351	              title="Pinned events"
352	              icon={require("assets/icons/pin.png")}
353	              onPress={() => navigation.navigate("pinnedEvents", { room })}
354	            />
355	          )}
356	        </Block>
357	        <LeaveRoom onPress={leaveRoom} />
358	      </IpadScreenWrapper>
359	    </ScreenLayout>
360	  );
361	};
362	
363	const styles = StyleSheet.create({
364	  caret: {
365	    transform: [{ rotate: "180deg" }],
366	    width: 24,
367	    height: 24,
368	    marginLeft: "auto",
369	  },
370	});
371	

