1	import { BottomSheetModalProvider } from "@gorhom/bottom-sheet";
2	import { Block, Text } from "@prototyp/skeletor";
3	import { useIsFocused } from "@react-navigation/native";
4	import type { NativeStackScreenProps } from "@react-navigation/native-stack";
5	import { useAtomValue } from "jotai";
6	import { AuthService } from "modules/auth/service/AuthService";
7	import { StorageAtoms } from "modules/storage/jotai/atoms";
8	import { UserService } from "modules/user/service/UserService";
9	import { useEffect, useState } from "react";
10	import { Image, type ImageSourcePropType, StyleSheet } from "react-native";
11	import { Button, GoBackHeader, ScreenLayout } from "shared/components";
12	import { Colors, TextSize } from "shared/styles";
13	import {
14	  SettingsListItem,
15	  SignOutBottomSheet,
16	  UserInfoItem,
17	} from "./fragments";
18	
19	type SettingsRouteName =
20	  | "notifications"
21	  | "screenLock"
22	  | "encryption"
23	  | "about"
24	  | "reportProblem";
25	
26	const ITEMS: {
27	  title: string;
28	  icon: ImageSourcePropType;
29	  routeName: SettingsRouteName;
30	}[] = [
31	  {
32	    title: "Notifications",
33	    icon: require("assets/icons/bell.png"),
34	    routeName: "notifications",
35	  },
36	  {
37	    title: "Screen Lock",
38	    icon: require("assets/icons/lock-key.png"),
39	    routeName: "screenLock",
40	  },
41	  {
42	    title: "Encryption",
43	    icon: require("assets/icons/key.png"),
44	    routeName: "encryption",
45	  },
46	  {
47	    title: "About",
48	    icon: require("assets/icons/info.png"),
49	    routeName: "about",
50	  },
51	];
52	
53	export const Settings: React.FC<NativeStackScreenProps<Routes, "settings">> = ({
54	  navigation,
55	}) => {
56	  const [isSignOutBottomSheetOpen, setIsSignOutBottomSheetOpen] =
57	    useState(false);
58	  const screenLockPin = useAtomValue(StorageAtoms.screenLockPin);
59	  const [blockedUserIds, setBlockedUserIds] = useState<string[]>([]);
60	  const canDeactivateAccount = AuthService.canDeactivateAccount();
61	  const isFocused = useIsFocused();
62	
63	  useEffect(() => {
64	    UserService.getBlockedUsers().then(setBlockedUserIds).catch(console.error);
65	  }, [isFocused]);
66	
67	  const handleOnPress = (routeName: SettingsRouteName) => {
68	    if (routeName === "screenLock") {
69	      if (screenLockPin) {
70	        navigation.navigate("verifyPin");
71	      } else navigation.navigate("setupScreenLock");
72	
73	      return;
74	    }
75	    navigation.navigate(routeName);
76	  };
77	
78	  return (
79	    <BottomSheetModalProvider>
80	    <ScreenLayout>
81	      <Block align="center" gap={40}>
82	        <GoBackHeader title="Settings" margins={0} />
83	        <UserInfoItem />
84	        <Block
85	          border={{ borderRadius: 16 }}
86	          width="100%"
87	          background={Colors.white5}
88	        >
89	          {ITEMS.slice(0, 3).map((item, index, array) => (
90	            <SettingsListItem
91	              key={item.title}
92	              title={item.title}
93	              icon={item.icon}
94	              onPress={() => handleOnPress(item.routeName)}
95	              showSeparator={
96	                index !== array.length - 1 || !!blockedUserIds.length
97	              }
98	            />
99	          ))}
100	          {!!blockedUserIds.length && (
101	            <SettingsListItem
102	              title="Blocked Users"
103	              icon={require("assets/icons/ban.png")}
104	              onPress={() =>
105	                navigation.navigate("blockedUsers", { blockedUserIds })
106	              }
107	              showSeparator={false}
108	            />
109	          )}
110	        </Block>
111	        <Block
112	          border={{ borderRadius: 16 }}
113	          width="100%"
114	          background={Colors.white5}
115	        >
116	          {ITEMS.slice(3).map((item, index, array) => (
117	            <SettingsListItem
118	              key={item.title}
119	              title={item.title}
120	              icon={item.icon}
121	              onPress={() => handleOnPress(item.routeName)}
122	              showSeparator={index !== array.length - 1}
123	            />
124	          ))}
125	        </Block>
126	        <Block
127	          border={{ borderRadius: 16 }}
128	          width="100%"
129	          background={Colors.white5}
130	        >
131	          <Button.Wrapper
132	            onPress={() => setIsSignOutBottomSheetOpen(true)}
133	            style={styles.button}
134	          >
135	            <Block
136	              flexDirection="row"
137	              align="center"
138	              gap={12}
139	              paddings={[20, 12]}
140	              width="100%"
141	              border={{ borderRadius: 16 }}
142	            >
143	              <Image
144	                source={require("assets/icons/sign-out.png")}
145	                width={24}
146	                height={24}
147	                tintColor={Colors.warning}
148	              />
149	              <Text size={TextSize.base} color={Colors.warning}>
150	                Sign Out
151	              </Text>
152	            </Block>
153	          </Button.Wrapper>
154	          {canDeactivateAccount && (
155	            <Button.Wrapper
156	              onPress={() => navigation.navigate("deactivateAccount")}
157	              style={styles.button}
158	            >
159	              <Block
160	                flexDirection="row"
161	                align="center"
162	                gap={12}
163	                paddings={[20, 12]}
164	                width="100%"
165	                border={{
166	                  borderRadius: 16,
167	                  borderTopWidth: 1,
168	                  borderColor: Colors.white5,
169	                }}
170	              >
171	                <Image
172	                  source={require("assets/icons/warning-triangle.png")}
173	                  width={24}
174	                  height={24}
175	                  tintColor={Colors.warning}
176	                />
177	                <Text size={TextSize.base} color={Colors.warning}>
178	                  Deactivate Account
179	                </Text>
180	              </Block>
181	            </Button.Wrapper>
182	          )}
183	        </Block>
184	      </Block>
185	      <SignOutBottomSheet
186	        isBottomSheetOpen={isSignOutBottomSheetOpen}
187	        setIsBottomSheetOpen={() => setIsSignOutBottomSheetOpen(false)}
188	      />
189	    </ScreenLayout>
190	    </BottomSheetModalProvider>
191	  );
192	};
193	
194	const styles = StyleSheet.create({
195	  button: {
196	    width: "100%",
197	  },
198	});
