1	import { Block, Text } from "@prototyp/skeletor";
2	import type { NativeStackScreenProps } from "@react-navigation/native-stack";
3	import { RecoveryState } from "@unomed/react-native-matrix-sdk";
4	import { useAtomValue } from "jotai";
5	import { EncryptionService } from "modules/encryption/service/EncryptionService";
6	import { NetworkAtoms } from "modules/network/jotai";
7	import { useEffect, useState } from "react";
8	import { Image, StyleSheet } from "react-native";
9	import {
10	  Button,
11	  GoBackHeader,
12	  Loading,
13	  RadioButton,
14	  ScreenLayout,
15	} from "shared/components";
16	import { Colors, TextSize } from "shared/styles";
17	import { offlineToastHelper } from "shared/utils";
18	import { DisableKeyStorageModal } from "./fragments";
19	
20	export const Encryption: React.FC<
21	  NativeStackScreenProps<Routes, "encryption">
22	> = ({ navigation }) => {
23	  const isOffline = useAtomValue(NetworkAtoms.isOffline);
24	  const [backupState, setBackupState] = useState<MappedBackupState>("unknown");
25	  const [recoveryState, setRecoveryState] = useState<RecoveryState>(
26	    RecoveryState.Unknown,
27	  );
28	  const [isLoading, setIsLoading] = useState<boolean>(true);
29	  const [isDisableKeyStorageModalVisible, setIsDisableKeyStorageModalVisible] =
30	    useState<boolean>(false);
31	  const isBackupEnabled =
32	    backupState === "enabled" ||
33	    (backupState === "unknown" &&
34	      (recoveryState === RecoveryState.Enabled ||
35	        recoveryState === RecoveryState.Incomplete));
36	  const isTransitioning =
37	    backupState === "enabling" || backupState === "disabling";
38	
39	  const recoveryText = () => {
40	    if (recoveryState === RecoveryState.Enabled) return "Change recovery key";
41	    if (recoveryState === RecoveryState.Disabled) {
42	      return "Set up a recovery key";
43	    }
44	    if (recoveryState === RecoveryState.Incomplete) {
45	      return "Enter existing recovery key and validate your device.";
46	    }
47	    return "Set up a recovery key";
48	  };
49	
50	  useEffect(() => {
51	    const listener = EncryptionService.subscribeToBackupState((state) => {
52	      setBackupState(state);
53	      setIsLoading(false);
54	    });
55	
56	    return () => {
57	      listener.cancel();
58	    };
59	  }, []);
60	
61	  useEffect(() => {
62	    const listener = EncryptionService.subscribeToRecoveryState((state) => {
63	      setRecoveryState(state);
64	      setIsLoading(false);
65	    });
66	
67	    return () => {
68	      listener.cancel();
69	    };
70	  }, []);
71	
72	  const handleToggleKeyStorage = async () => {
73	    try {
74	      if (isBackupEnabled) {
75	        setIsDisableKeyStorageModalVisible(true);
76	        return;
77	      }
78	
79	      // Enable backups when state is unknown (backup not enabled)
80	      setIsLoading(true);
81	      await EncryptionService.enableBackups();
82	      setIsLoading(false);
83	    } catch (error) {
84	      console.error("Failed to toggle key storage:", error);
85	      offlineToastHelper("Failed to toggle key storage");
86	    }
87	  };
88	
89	  return (
90	    <ScreenLayout>
91	      <Block flex={1} align="center" gap={40}>
92	        <GoBackHeader title="Encryption" margins={0} />
93	        {isOffline ? (
94	          <Block flex={1} align="center" justify="center" gap={16}>
95	            <Image
96	              source={require("assets/icons/wifi-slash.png")}
97	              style={styles.wifiIcon}
98	            />
99	            <Text size={TextSize.base} color={Colors.white50}>
100	              No internet connection
101	            </Text>
102	            <Text size={TextSize.tiny} color={Colors.white50}>
103	              Encryption settings can't be changed while offline.
104	            </Text>
105	          </Block>
106	        ) : (
