31	export const PinnedEvents: FC<
32	  NativeStackScreenProps<Routes, "pinnedEvents">
33	> = ({ route }) => {
34	  const { room } = route.params;
35	  const pinnedEventIds = useAtomValue(TimelineAtoms.pinnedEventIds);
36	  const [events, setEvents] = useState<EventTimelineItem[]>([]);
37	  const [loading, setLoading] = useState(true);
38	
39	  useEffect(() => {
40	    if (!room) return;
41	
42	    setEvents([]);
43	
44	    const initPinnedTimeline = async () => {
45	      try {
46	        if (pinnedEventIds.length === 0) {
47	          setEvents([]);
48	          setLoading(false);
49	          return;
50	        }
51	
52	        const fetchedEvents: EventTimelineItem[] = [];
53	
54	        for (const id of pinnedEventIds) {
55	          try {
56	            const focusedTimeline = await room.timelineWithConfiguration({
57	              focus: new TimelineFocus.Event({
58	                eventId: id,
59	                numContextEvents: 0,
60	                hideThreadedEvents: false,
61	              }),
62	              filter: new TimelineFilter.All(),
63	              internalIdPrefix: undefined,
64	              dateDividerMode: DateDividerMode.Daily,
65	              trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
66	              reportUtds: false,
67	            });
68	            const item =
69	              await focusedTimeline.getEventTimelineItemByEventId(id);
70	            if (!item) return;
71	            fetchedEvents.push(item);
72	          } catch (error) {
73	            console.warn("Failed to load pinned event:", id, error);
74	          }
75	        }
76	
77	        setEvents(fetchedEvents);
78	        setLoading(false);
79	      } catch (error) {
80	        console.error("Failed to initialize pinned events timeline:", error);
81	        setLoading(false);
82	      }
83	    };
84	
85	    initPinnedTimeline();
86	
87	    return () => {};
88	  }, [room]);
89	
90	  return (
