96	          return (
97	            <Block paddings={{ paddingHorizontal: 16 }}>
98	              <SingleMessageType
99	                roomId={room.id()}
100	                event={item}
101	                isPreviousSameSender={false}
102	              />
103	            </Block>
104	          );
105	        }}
106	        keyExtractor={keyExtractor}
107	        contentContainerStyle={styles.listContent}
108	        ListEmptyComponent={
109	          <Block align="center" justify="center" flex={1} paddings={40}>
